import { env } from "cloudflare:workers";
import { EffectNotDelivered } from "@actord/toolkit/runtime";
import { overrideBudget, overrideEffect, resetSeams, settle } from "@actord/toolkit/testing";
import { afterEach, expect, it } from "vitest";
import system from "../system.ts";
import { board, gateway, scriptedModel, status, submit } from "./helpers.ts";

afterEach(() => resetSeams());

it("[model-unavailable][budget] an unreachable model is tried exactly maxAttempts times, then the item goes to a person", async () => {
  const calls = scriptedModel({ "Login page blank": new EffectNotDelivered("model API unreachable") });
  gateway("accept");
  await submit("mu-1", "Login page blank");
  await settle(env, system);
  expect(calls).toHaveLength(system.actors.Analyst.budget.maxAttempts);
  const row = (await board()).find((r) => r.item_id === "mu-1");
  expect(row).toMatchObject({ status: "needs_human" });
  expect(row?.reason).toMatch(/model failed: model API unreachable/);
});

it("[model-timeout] a model that never answers is cut off by the budget's timeout and the item goes to a person", async () => {
  overrideBudget("Analyst", { timeoutMs: 30 });
  let calls = 0;
  overrideEffect("model.analyze", {
    run: () => {
      calls++;
      return new Promise(() => {}); // never settles
    },
  });
  await submit("mt-1", "Cache hit rate dropped");
  await settle(env, system);
  expect(calls).toBe(2);
  const row = (await board()).find((r) => r.item_id === "mt-1");
  // Retried (a model call has no side effects), then unknown: reported as in doubt, never as an answer.
  expect(row).toMatchObject({ status: "needs_human" });
  expect(row?.reason).toMatch(/model in_doubt: effect timed out after 30ms/);
});

it("[model-output-invalid] model output that fails the schema is never acted on", async () => {
  scriptedModel({ "Weird request": { category: "urgent!!", priority: "HIGH", summary: 42 } });
  const sent = gateway("accept");
  await submit("mi-1", "Weird request");
  await settle(env, system);
  expect(await status("mi-1")).toBe("needs_human");
  expect((await board()).find((r) => r.item_id === "mi-1")?.reason).toMatch(/model output failed validation/);
  expect(sent).toEqual([]);
});

briefing-desk.tests/reentrancy.test.ts:
import { env } from "cloudflare:workers";
import { ingress } from "@actord/toolkit/runtime";
import { resetSeams, settle } from "@actord/toolkit/testing";
import { afterEach, expect, it } from "vitest";
import system from "../system.ts";
import { analysis, deferredModel, gateway, status, submit } from "./helpers.ts";

afterEach(() => resetSeams());

async function until(pred: () => boolean | Promise<boolean>, what: string) {
  for (let i = 0; i < 200; i++) {
    if (await pred()) return;
    await new Promise((r) => setTimeout(r, 5));
  }
  throw new Error(`timed out waiting for ${what}`);
}

it("[reentrancy] a cancellation handled while the model call is in flight makes the late result stale", async () => {
  const model = deferredModel();
  const sent = gateway("accept");

  const submitting = submit("re-1", "Payment provider latency spike");
  await until(() => model.state.calls === 1, "the model call to start");

  // The analyst is waiting on the model outside any transaction, so the control message gets in.
  const cancel = await ingress(env, system, "Analyst", "item.cancelled", { itemId: "re-1", reason: "resolved upstream" }, { key: "re-1" });
  expect(cancel.status).toBe("handled");
  await until(async () => (await status("re-1")) === "cancelled", "the board to show the cancellation");

  // Now the model answers "urgent" for the old request. It must not produce a briefing.
  model.resolve(analysis("incident", "high"));
  await submitting;
  await settle(env, system);

  expect(await status("re-1")).toBe("cancelled");
  expect(sent).toEqual([]);
  const item = await env.ANALYST.getByName("re-1").item();
  expect(item).toMatchObject({ status: "cancelled", generation: 2 });
});

